-- =============================================================================
-- SEED DATA – sinh tự động bởi scripts/generate-seed-sql.ts (KHÔNG sửa tay)
-- 141 mô phỏng thật từ 18 nguồn. Chỉ metadata + liên kết tới nhà cung cấp.
-- =============================================================================

insert into public.sources (name, slug, description, website_url, license, license_url, country, allows_embed, is_verified, is_active) values
  ('PhET', 'phet', 'PhET Interactive Simulations (Đại học Colorado Boulder) – mô phỏng tương tác miễn phí về vật lý, hóa học, sinh học, khoa học Trái đất và toán học.', 'https://phet.colorado.edu', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'US', true, true, true),
  ('ChemCollective', 'chemcollective', 'ChemCollective (Carnegie Mellon University) – phòng thí nghiệm hóa học ảo và bài tập dựa trên tình huống.', 'https://chemcollective.org', 'Free educational use (see provider terms)', null, 'US', false, true, true),
  ('Concord Consortium', 'concord-consortium', 'Concord Consortium – tổ chức phi lợi nhuận phát triển mô hình, mô phỏng và công cụ dữ liệu mã nguồn mở cho giáo dục STEM.', 'https://concord.org', 'Open educational resource (see provider terms)', null, 'US', false, true, true),
  ('LabXchange', 'labxchange', 'LabXchange (Harvard) – nền tảng học tập miễn phí với phòng thí nghiệm ảo và nội dung khoa học.', 'https://www.labxchange.org', 'Free educational use (see provider terms)', null, 'US', false, true, true),
  ('NOVA Labs', 'nova-labs', 'NOVA Labs (PBS/GBH) – các phòng thí nghiệm số dạng khám phá về tiến hóa, năng lượng, Mặt Trời, mây...', 'https://www.pbs.org/wgbh/nova/labs/', 'Free educational use (see provider terms)', null, 'US', false, true, true),
  ('Desmos', 'desmos', 'Desmos – máy tính đồ thị, hình học và khoa học trực tuyến miễn phí.', 'https://www.desmos.com', 'Free to use (see provider terms)', null, 'US', false, true, true),
  ('GeoGebra', 'geogebra', 'GeoGebra – phần mềm toán học động cho hình học, đại số, đồ thị và 3D.', 'https://www.geogebra.org', 'Free for non-commercial use (see provider terms)', null, 'AT', false, true, true),
  ('NASA', 'nasa', 'NASA Eyes – trực quan hóa 3D dữ liệu thật về Hệ Mặt Trời, Trái Đất và ngoại hành tinh.', 'https://eyes.nasa.gov', 'NASA media usage guidelines', 'https://www.nasa.gov/nasa-brand-center/images-and-media/', 'US', false, true, true),
  ('Stellarium Web', 'stellarium-web', 'Stellarium Web – cung thiên văn trực tuyến hiển thị bầu trời theo thời gian thực.', 'https://stellarium-web.org', 'Free to use (see provider terms)', null, 'FR', false, true, true),
  ('Scratch', 'scratch', 'Scratch (MIT Media Lab) – ngôn ngữ lập trình khối cho trẻ em và người mới bắt đầu.', 'https://scratch.mit.edu', 'Free to use; community projects CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0/', 'US', false, true, true),
  ('Blockly Games', 'blockly-games', 'Blockly Games – chuỗi trò chơi học lập trình bằng khối lệnh, mã nguồn mở.', 'https://blockly.games', 'Apache License 2.0', 'https://www.apache.org/licenses/LICENSE-2.0', 'US', false, true, true),
  ('Falstad', 'falstad', 'Các mô phỏng vật lý/điện tử mã nguồn mở của Paul Falstad (CircuitJS, Ripple Tank...).', 'https://www.falstad.com', 'GPL (see provider terms)', null, 'US', false, true, true),
  ('MolView', 'molview', 'MolView – công cụ vẽ và xem cấu trúc phân tử 2D/3D trên trình duyệt.', 'https://molview.org', 'Free to use (see provider terms)', null, 'NL', false, true, true),
  ('Chrome Music Lab', 'chrome-music-lab', 'Chrome Music Lab – các thí nghiệm âm thanh và âm nhạc trực quan trên trình duyệt.', 'https://musiclab.chromeexperiments.com', 'Free to use (see provider terms)', null, 'US', false, true, true),
  ('USGS', 'usgs', 'Cục Khảo sát Địa chất Hoa Kỳ – dữ liệu động đất và khoa học Trái Đất công khai.', 'https://www.usgs.gov', 'Public domain (U.S. Government work)', 'https://www.usgs.gov/information-policies-and-instructions/copyrights-and-credits', 'US', false, true, true),
  ('earth.nullschool', 'earth-nullschool', 'Bản đồ trực quan gió, hải lưu và điều kiện khí quyển toàn cầu gần thời gian thực.', 'https://earth.nullschool.net', 'Free to use (see provider terms)', null, 'US', false, true, true),
  ('Global Forest Watch', 'global-forest-watch', 'Global Forest Watch (World Resources Institute) – bản đồ và dữ liệu mở về rừng toàn cầu.', 'https://www.globalforestwatch.org', 'Free to use; data mostly CC BY 4.0 (see provider terms)', null, 'US', false, true, true),
  ('Yenka', 'yenka', 'Yenka – phần mềm mô phỏng khoa học, công nghệ và toán học (miễn phí cho sử dụng tại nhà, trả phí cho trường học).', 'https://www.yenka.com', 'Commercial (free home licence available)', null, 'GB', false, true, true)
on conflict (slug) do update set
  name = excluded.name, description = excluded.description, website_url = excluded.website_url,
  license = excluded.license, license_url = excluded.license_url, country = excluded.country,
  allows_embed = excluded.allows_embed;

insert into public.simulations (
  slug, title, description, short_description, subject_id, grade_min, grade_max, topic, subtopic,
  simulation_type, source_id, source_url, simulation_url, embed_url, thumbnail_url, language,
  license, license_url, license_category, difficulty, duration_minutes, learning_objectives,
  required_equipment, tags, is_free, is_verified, is_featured, is_active, status
) values
  ('circuit-construction-kit-dc', 'Circuit Construction Kit: DC', 'Lắp mạch điện một chiều với pin, bóng đèn, điện trở và công tắc; đo hiệu điện thế và cường độ dòng điện bằng dụng cụ ảo.', 'Lắp mạch điện một chiều với pin, bóng đèn, điện trở và công tắc; đo hiệu điện thế và cường độ dòng điện bằng dụng cụ ảo.', (select id from public.subjects where slug = 'physics'), 7, 12, 'Điện học', 'Mạch điện một chiều', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/circuit-construction-kit-dc', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-dc/latest/circuit-construction-kit-dc_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-dc/latest/circuit-construction-kit-dc_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-dc/latest/circuit-construction-kit-dc-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 45, array['Lắp được mạch điện nối tiếp và song song từ sơ đồ cho trước.', 'Dùng ampe kế, vôn kế ảo để đo cường độ dòng điện và hiệu điện thế.', 'So sánh độ sáng bóng đèn trong mạch nối tiếp và song song.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'mạch điện', 'circuit', 'điện trở', 'resistance', 'voltage', 'current', 'ohm', 'ampe kế', 'vôn kế']::text[], true, true, true, true, 'published'),
  ('circuit-construction-kit-dc-virtual-lab', 'Circuit Construction Kit: DC – Virtual Lab', 'Phiên bản phòng thí nghiệm ảo của bộ lắp mạch điện DC, cho phép thay đổi điện trở trong của nguồn và điện trở suất của dây.', 'Phiên bản phòng thí nghiệm ảo của bộ lắp mạch điện DC, cho phép thay đổi điện trở trong của nguồn và điện trở suất của dây.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Điện học', 'Mạch điện một chiều', 'virtual_lab', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/circuit-construction-kit-dc-virtual-lab', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-dc-virtual-lab/latest/circuit-construction-kit-dc-virtual-lab_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-dc-virtual-lab/latest/circuit-construction-kit-dc-virtual-lab_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-dc-virtual-lab/latest/circuit-construction-kit-dc-virtual-lab-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 45, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'mạch điện', 'circuit', 'virtual lab', 'điện trở trong', 'internal resistance', 'ohm']::text[], true, true, false, true, 'published'),
  ('circuit-construction-kit-ac', 'Circuit Construction Kit: AC', 'Khảo sát mạch điện xoay chiều có tụ điện, cuộn cảm và điện trở; quan sát dòng điện, hiệu điện thế thay đổi theo thời gian.', 'Khảo sát mạch điện xoay chiều có tụ điện, cuộn cảm và điện trở; quan sát dòng điện, hiệu điện thế thay đổi theo thời gian.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Điện học', 'Dòng điện xoay chiều', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/circuit-construction-kit-ac', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-ac/latest/circuit-construction-kit-ac_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-ac/latest/circuit-construction-kit-ac_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-ac/latest/circuit-construction-kit-ac-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 45, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'dòng điện xoay chiều', 'alternating current', 'tụ điện', 'capacitor', 'cuộn cảm', 'inductor', 'circuit']::text[], true, true, false, true, 'published'),
  ('circuit-construction-kit-ac-virtual-lab', 'Circuit Construction Kit: AC – Virtual Lab', 'Phòng thí nghiệm ảo về mạch xoay chiều với các thông số linh kiện có thể điều chỉnh chi tiết.', 'Phòng thí nghiệm ảo về mạch xoay chiều với các thông số linh kiện có thể điều chỉnh chi tiết.', (select id from public.subjects where slug = 'physics'), 11, 12, 'Điện học', 'Dòng điện xoay chiều', 'virtual_lab', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/circuit-construction-kit-ac-virtual-lab', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-ac-virtual-lab/latest/circuit-construction-kit-ac-virtual-lab_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-ac-virtual-lab/latest/circuit-construction-kit-ac-virtual-lab_all.html', 'https://phet.colorado.edu/sims/html/circuit-construction-kit-ac-virtual-lab/latest/circuit-construction-kit-ac-virtual-lab-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 45, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'dòng điện xoay chiều', 'ac circuit', 'virtual lab', 'capacitor', 'inductor']::text[], true, true, false, true, 'published'),
  ('ohms-law', 'Ohm''s Law', 'Trực quan hóa mối liên hệ U = I·R: thay đổi hiệu điện thế và điện trở để thấy cường độ dòng điện thay đổi như thế nào.', 'Trực quan hóa mối liên hệ U = I·R: thay đổi hiệu điện thế và điện trở để thấy cường độ dòng điện thay đổi như thế nào.', (select id from public.subjects where slug = 'physics'), 7, 11, 'Điện học', 'Định luật Ohm', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/ohms-law', 'https://phet.colorado.edu/sims/html/ohms-law/latest/ohms-law_all.html', 'https://phet.colorado.edu/sims/html/ohms-law/latest/ohms-law_all.html', 'https://phet.colorado.edu/sims/html/ohms-law/latest/ohms-law-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, array['Phát biểu được định luật Ohm U = I·R.', 'Dự đoán sự thay đổi cường độ dòng điện khi thay đổi U hoặc R.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'định luật ohm', 'ohm', 'điện trở', 'hiệu điện thế', 'cường độ dòng điện', 'voltage', 'current', 'resistance']::text[], true, true, false, true, 'published'),
  ('resistance-in-a-wire', 'Resistance in a Wire', 'Khám phá điện trở của dây dẫn phụ thuộc vào điện trở suất, chiều dài và tiết diện của dây.', 'Khám phá điện trở của dây dẫn phụ thuộc vào điện trở suất, chiều dài và tiết diện của dây.', (select id from public.subjects where slug = 'physics'), 8, 11, 'Điện học', 'Điện trở của dây dẫn', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/resistance-in-a-wire', 'https://phet.colorado.edu/sims/html/resistance-in-a-wire/latest/resistance-in-a-wire_all.html', 'https://phet.colorado.edu/sims/html/resistance-in-a-wire/latest/resistance-in-a-wire_all.html', 'https://phet.colorado.edu/sims/html/resistance-in-a-wire/latest/resistance-in-a-wire-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'điện trở', 'điện trở suất', 'resistivity', 'dây dẫn', 'resistance']::text[], true, true, false, true, 'published'),
  ('capacitor-lab-basics', 'Capacitor Lab: Basics', 'Tìm hiểu điện dung của tụ điện phẳng phụ thuộc vào diện tích bản và khoảng cách giữa hai bản; quan sát điện tích và năng lượng tích trữ.', 'Tìm hiểu điện dung của tụ điện phẳng phụ thuộc vào diện tích bản và khoảng cách giữa hai bản; quan sát điện tích và năng lượng tích trữ.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Điện học', 'Tụ điện', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/capacitor-lab-basics', 'https://phet.colorado.edu/sims/html/capacitor-lab-basics/latest/capacitor-lab-basics_all.html', 'https://phet.colorado.edu/sims/html/capacitor-lab-basics/latest/capacitor-lab-basics_all.html', 'https://phet.colorado.edu/sims/html/capacitor-lab-basics/latest/capacitor-lab-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'tụ điện', 'capacitor', 'điện dung', 'capacitance', 'điện trường']::text[], true, true, false, true, 'published'),
  ('charges-and-fields', 'Charges and Fields', 'Đặt các điện tích điểm và quan sát điện trường, điện thế và các đường đẳng thế xung quanh chúng.', 'Đặt các điện tích điểm và quan sát điện trường, điện thế và các đường đẳng thế xung quanh chúng.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Điện học', 'Điện trường', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/charges-and-fields', 'https://phet.colorado.edu/sims/html/charges-and-fields/latest/charges-and-fields_all.html', 'https://phet.colorado.edu/sims/html/charges-and-fields/latest/charges-and-fields_all.html', 'https://phet.colorado.edu/sims/html/charges-and-fields/latest/charges-and-fields-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'điện trường', 'electric field', 'điện tích', 'charge', 'điện thế', 'equipotential']::text[], true, true, false, true, 'published'),
  ('coulombs-law', 'Coulomb''s Law', 'Đo lực tương tác giữa hai điện tích điểm và khám phá sự phụ thuộc vào độ lớn điện tích và khoảng cách.', 'Đo lực tương tác giữa hai điện tích điểm và khám phá sự phụ thuộc vào độ lớn điện tích và khoảng cách.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Điện học', 'Định luật Coulomb', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/coulombs-law', 'https://phet.colorado.edu/sims/html/coulombs-law/latest/coulombs-law_all.html', 'https://phet.colorado.edu/sims/html/coulombs-law/latest/coulombs-law_all.html', 'https://phet.colorado.edu/sims/html/coulombs-law/latest/coulombs-law-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'định luật coulomb', 'coulomb', 'lực điện', 'electric force', 'điện tích']::text[], true, true, false, true, 'published'),
  ('balloons-and-static-electricity', 'Balloons and Static Electricity', 'Cọ xát quả bóng bay vào áo len để quan sát sự dịch chuyển điện tích và hiện tượng hút – đẩy do tĩnh điện.', 'Cọ xát quả bóng bay vào áo len để quan sát sự dịch chuyển điện tích và hiện tượng hút – đẩy do tĩnh điện.', (select id from public.subjects where slug = 'physics'), 3, 9, 'Điện học', 'Tĩnh điện', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/balloons-and-static-electricity', 'https://phet.colorado.edu/sims/html/balloons-and-static-electricity/latest/balloons-and-static-electricity_all.html', 'https://phet.colorado.edu/sims/html/balloons-and-static-electricity/latest/balloons-and-static-electricity_all.html', 'https://phet.colorado.edu/sims/html/balloons-and-static-electricity/latest/balloons-and-static-electricity-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'tĩnh điện', 'static electricity', 'bóng bay', 'balloon', 'điện tích', 'nhiễm điện']::text[], true, true, false, true, 'published'),
  ('john-travoltage', 'John Travoltage', 'Tích điện cho nhân vật bằng cách cọ chân lên thảm rồi quan sát tia lửa điện khi tay chạm vào nắm cửa.', 'Tích điện cho nhân vật bằng cách cọ chân lên thảm rồi quan sát tia lửa điện khi tay chạm vào nắm cửa.', (select id from public.subjects where slug = 'physics'), 3, 9, 'Điện học', 'Tĩnh điện', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/john-travoltage', 'https://phet.colorado.edu/sims/html/john-travoltage/latest/john-travoltage_all.html', 'https://phet.colorado.edu/sims/html/john-travoltage/latest/john-travoltage_all.html', 'https://phet.colorado.edu/sims/html/john-travoltage/latest/john-travoltage-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 10, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'tĩnh điện', 'static electricity', 'phóng điện', 'discharge', 'điện tích']::text[], true, true, false, true, 'published'),
  ('faradays-law', 'Faraday''s Law', 'Di chuyển nam châm qua cuộn dây để tạo ra dòng điện cảm ứng; khám phá vai trò của tốc độ và số vòng dây.', 'Di chuyển nam châm qua cuộn dây để tạo ra dòng điện cảm ứng; khám phá vai trò của tốc độ và số vòng dây.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Điện từ học', 'Cảm ứng điện từ', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/faradays-law', 'https://phet.colorado.edu/sims/html/faradays-law/latest/faradays-law_all.html', 'https://phet.colorado.edu/sims/html/faradays-law/latest/faradays-law_all.html', 'https://phet.colorado.edu/sims/html/faradays-law/latest/faradays-law-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'cảm ứng điện từ', 'electromagnetic induction', 'faraday', 'nam châm', 'magnet', 'cuộn dây']::text[], true, true, false, true, 'published'),
  ('forces-and-motion-basics', 'Forces and Motion: Basics', 'Khám phá lực cân bằng và không cân bằng qua trò kéo co, đẩy vật và ảnh hưởng của ma sát lên chuyển động.', 'Khám phá lực cân bằng và không cân bằng qua trò kéo co, đẩy vật và ảnh hưởng của ma sát lên chuyển động.', (select id from public.subjects where slug = 'physics'), 3, 8, 'Cơ học', 'Lực và chuyển động', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/forces-and-motion-basics', 'https://phet.colorado.edu/sims/html/forces-and-motion-basics/latest/forces-and-motion-basics_all.html', 'https://phet.colorado.edu/sims/html/forces-and-motion-basics/latest/forces-and-motion-basics_all.html', 'https://phet.colorado.edu/sims/html/forces-and-motion-basics/latest/forces-and-motion-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 30, array['Nhận biết lực cân bằng và lực không cân bằng.', 'Giải thích ảnh hưởng của ma sát và khối lượng đến chuyển động.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'lực', 'force', 'chuyển động', 'motion', 'ma sát', 'friction', 'định luật newton', 'kéo co']::text[], true, true, false, true, 'published'),
  ('friction', 'Friction', 'Quan sát ở cấp độ phân tử điều gì xảy ra khi hai bề mặt cọ xát vào nhau và vì sao ma sát làm vật nóng lên.', 'Quan sát ở cấp độ phân tử điều gì xảy ra khi hai bề mặt cọ xát vào nhau và vì sao ma sát làm vật nóng lên.', (select id from public.subjects where slug = 'physics'), 4, 8, 'Cơ học', 'Ma sát', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/friction', 'https://phet.colorado.edu/sims/html/friction/latest/friction_all.html', 'https://phet.colorado.edu/sims/html/friction/latest/friction_all.html', 'https://phet.colorado.edu/sims/html/friction/latest/friction-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'ma sát', 'friction', 'nhiệt', 'heat', 'phân tử']::text[], true, true, false, true, 'published'),
  ('projectile-motion', 'Projectile Motion', 'Bắn các vật thể từ khẩu pháo và khảo sát tầm xa, độ cao cực đại theo góc bắn, vận tốc đầu và sức cản không khí.', 'Bắn các vật thể từ khẩu pháo và khảo sát tầm xa, độ cao cực đại theo góc bắn, vận tốc đầu và sức cản không khí.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Cơ học', 'Chuyển động ném', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/projectile-motion', 'https://phet.colorado.edu/sims/html/projectile-motion/latest/projectile-motion_all.html', 'https://phet.colorado.edu/sims/html/projectile-motion/latest/projectile-motion_all.html', 'https://phet.colorado.edu/sims/html/projectile-motion/latest/projectile-motion-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, array['Xác định ảnh hưởng của góc bắn và vận tốc ban đầu đến tầm xa.', 'Phân tích chuyển động ném thành hai chuyển động thành phần.', 'Nhận xét vai trò của sức cản không khí.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'chuyển động ném', 'ném xiên', 'projectile motion', 'quỹ đạo', 'trajectory', 'sức cản không khí']::text[], true, true, true, true, 'published'),
  ('pendulum-lab', 'Pendulum Lab', 'Đo chu kỳ con lắc đơn khi thay đổi chiều dài, khối lượng, biên độ và gia tốc trọng trường (kể cả trên các hành tinh khác).', 'Đo chu kỳ con lắc đơn khi thay đổi chiều dài, khối lượng, biên độ và gia tốc trọng trường (kể cả trên các hành tinh khác).', (select id from public.subjects where slug = 'physics'), 9, 12, 'Dao động', 'Con lắc đơn', 'virtual_lab', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/pendulum-lab', 'https://phet.colorado.edu/sims/html/pendulum-lab/latest/pendulum-lab_all.html', 'https://phet.colorado.edu/sims/html/pendulum-lab/latest/pendulum-lab_all.html', 'https://phet.colorado.edu/sims/html/pendulum-lab/latest/pendulum-lab-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, array['Xác định các yếu tố ảnh hưởng đến chu kỳ con lắc đơn.', 'Dùng con lắc để xác định gia tốc trọng trường.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'con lắc', 'pendulum', 'dao động', 'chu kỳ', 'period', 'gia tốc trọng trường']::text[], true, true, false, true, 'published'),
  ('masses-and-springs', 'Masses and Springs', 'Treo vật nặng vào lò xo để khám phá định luật Hooke, dao động điều hòa và sự chuyển hóa năng lượng.', 'Treo vật nặng vào lò xo để khám phá định luật Hooke, dao động điều hòa và sự chuyển hóa năng lượng.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Dao động', 'Con lắc lò xo', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/masses-and-springs', 'https://phet.colorado.edu/sims/html/masses-and-springs/latest/masses-and-springs_all.html', 'https://phet.colorado.edu/sims/html/masses-and-springs/latest/masses-and-springs_all.html', 'https://phet.colorado.edu/sims/html/masses-and-springs/latest/masses-and-springs-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'lò xo', 'spring', 'con lắc lò xo', 'dao động', 'định luật hooke', 'năng lượng']::text[], true, true, false, true, 'published'),
  ('masses-and-springs-basics', 'Masses and Springs: Basics', 'Phiên bản cơ bản giúp học sinh THCS thấy độ giãn của lò xo phụ thuộc vào khối lượng vật treo và độ cứng lò xo.', 'Phiên bản cơ bản giúp học sinh THCS thấy độ giãn của lò xo phụ thuộc vào khối lượng vật treo và độ cứng lò xo.', (select id from public.subjects where slug = 'physics'), 6, 9, 'Cơ học', 'Lò xo', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/masses-and-springs-basics', 'https://phet.colorado.edu/sims/html/masses-and-springs-basics/latest/masses-and-springs-basics_all.html', 'https://phet.colorado.edu/sims/html/masses-and-springs-basics/latest/masses-and-springs-basics_all.html', 'https://phet.colorado.edu/sims/html/masses-and-springs-basics/latest/masses-and-springs-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'lò xo', 'spring', 'độ giãn', 'khối lượng', 'mass']::text[], true, true, false, true, 'published'),
  ('hookes-law', 'Hooke''s Law', 'Kéo và nén lò xo để tìm mối liên hệ giữa lực tác dụng, độ biến dạng và độ cứng; ghép lò xo nối tiếp và song song.', 'Kéo và nén lò xo để tìm mối liên hệ giữa lực tác dụng, độ biến dạng và độ cứng; ghép lò xo nối tiếp và song song.', (select id from public.subjects where slug = 'physics'), 8, 12, 'Cơ học', 'Định luật Hooke', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/hookes-law', 'https://phet.colorado.edu/sims/html/hookes-law/latest/hookes-law_all.html', 'https://phet.colorado.edu/sims/html/hookes-law/latest/hookes-law_all.html', 'https://phet.colorado.edu/sims/html/hookes-law/latest/hookes-law-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'định luật hooke', 'hookes law', 'lò xo', 'spring', 'độ cứng', 'lực đàn hồi']::text[], true, true, false, true, 'published'),
  ('energy-skate-park-basics', 'Energy Skate Park: Basics', 'Quan sát sự chuyển hóa giữa động năng và thế năng của người trượt ván trên đường dốc, có và không có ma sát.', 'Quan sát sự chuyển hóa giữa động năng và thế năng của người trượt ván trên đường dốc, có và không có ma sát.', (select id from public.subjects where slug = 'physics'), 6, 9, 'Năng lượng', 'Cơ năng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/energy-skate-park-basics', 'https://phet.colorado.edu/sims/html/energy-skate-park-basics/latest/energy-skate-park-basics_all.html', 'https://phet.colorado.edu/sims/html/energy-skate-park-basics/latest/energy-skate-park-basics_all.html', 'https://phet.colorado.edu/sims/html/energy-skate-park-basics/latest/energy-skate-park-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 30, array['Mô tả sự chuyển hóa giữa động năng và thế năng.', 'Giải thích vì sao cơ năng giảm khi có ma sát.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'năng lượng', 'energy', 'động năng', 'thế năng', 'cơ năng', 'bảo toàn năng lượng', 'trượt ván']::text[], true, true, true, true, 'published'),
  ('energy-skate-park', 'Energy Skate Park', 'Thiết kế đường trượt riêng, đo năng lượng bằng biểu đồ và kiểm chứng định luật bảo toàn cơ năng.', 'Thiết kế đường trượt riêng, đo năng lượng bằng biểu đồ và kiểm chứng định luật bảo toàn cơ năng.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Năng lượng', 'Bảo toàn cơ năng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/energy-skate-park', 'https://phet.colorado.edu/sims/html/energy-skate-park/latest/energy-skate-park_all.html', 'https://phet.colorado.edu/sims/html/energy-skate-park/latest/energy-skate-park_all.html', 'https://phet.colorado.edu/sims/html/energy-skate-park/latest/energy-skate-park-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 45, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'bảo toàn năng lượng', 'energy conservation', 'động năng', 'thế năng', 'nhiệt năng', 'ma sát']::text[], true, true, false, true, 'published'),
  ('gravity-and-orbits', 'Gravity and Orbits', 'Điều chỉnh khối lượng và khoảng cách giữa Mặt Trời, Trái Đất, Mặt Trăng để thấy lực hấp dẫn quyết định quỹ đạo.', 'Điều chỉnh khối lượng và khoảng cách giữa Mặt Trời, Trái Đất, Mặt Trăng để thấy lực hấp dẫn quyết định quỹ đạo.', (select id from public.subjects where slug = 'physics'), 6, 12, 'Thiên văn', 'Lực hấp dẫn', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/gravity-and-orbits', 'https://phet.colorado.edu/sims/html/gravity-and-orbits/latest/gravity-and-orbits_all.html', 'https://phet.colorado.edu/sims/html/gravity-and-orbits/latest/gravity-and-orbits_all.html', 'https://phet.colorado.edu/sims/html/gravity-and-orbits/latest/gravity-and-orbits-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, array['Giải thích vai trò của lực hấp dẫn trong chuyển động quỹ đạo.', 'Dự đoán điều gì xảy ra với quỹ đạo khi thay đổi khối lượng.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'hấp dẫn', 'gravity', 'quỹ đạo', 'orbit', 'mặt trời', 'trái đất', 'mặt trăng']::text[], true, true, false, true, 'published'),
  ('gravity-force-lab', 'Gravity Force Lab', 'Đo lực hấp dẫn giữa hai vật và khám phá sự phụ thuộc vào khối lượng và khoảng cách theo định luật Newton.', 'Đo lực hấp dẫn giữa hai vật và khám phá sự phụ thuộc vào khối lượng và khoảng cách theo định luật Newton.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Cơ học', 'Định luật vạn vật hấp dẫn', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/gravity-force-lab', 'https://phet.colorado.edu/sims/html/gravity-force-lab/latest/gravity-force-lab_all.html', 'https://phet.colorado.edu/sims/html/gravity-force-lab/latest/gravity-force-lab_all.html', 'https://phet.colorado.edu/sims/html/gravity-force-lab/latest/gravity-force-lab-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'vạn vật hấp dẫn', 'gravity force', 'newton', 'khối lượng', 'khoảng cách']::text[], true, true, false, true, 'published'),
  ('gravity-force-lab-basics', 'Gravity Force Lab: Basics', 'Phiên bản cơ bản giúp nhận biết lực hấp dẫn tăng khi khối lượng tăng và giảm khi khoảng cách tăng.', 'Phiên bản cơ bản giúp nhận biết lực hấp dẫn tăng khi khối lượng tăng và giảm khi khoảng cách tăng.', (select id from public.subjects where slug = 'physics'), 6, 9, 'Cơ học', 'Lực hấp dẫn', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/gravity-force-lab-basics', 'https://phet.colorado.edu/sims/html/gravity-force-lab-basics/latest/gravity-force-lab-basics_all.html', 'https://phet.colorado.edu/sims/html/gravity-force-lab-basics/latest/gravity-force-lab-basics_all.html', 'https://phet.colorado.edu/sims/html/gravity-force-lab-basics/latest/gravity-force-lab-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'hấp dẫn', 'gravity', 'khối lượng', 'mass', 'khoảng cách']::text[], true, true, false, true, 'published'),
  ('keplers-laws', 'Kepler''s Laws', 'Khám phá ba định luật Kepler: quỹ đạo elip, diện tích quét bằng nhau và mối liên hệ giữa chu kỳ và bán trục lớn.', 'Khám phá ba định luật Kepler: quỹ đạo elip, diện tích quét bằng nhau và mối liên hệ giữa chu kỳ và bán trục lớn.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Thiên văn', 'Định luật Kepler', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/keplers-laws', 'https://phet.colorado.edu/sims/html/keplers-laws/latest/keplers-laws_all.html', 'https://phet.colorado.edu/sims/html/keplers-laws/latest/keplers-laws_all.html', 'https://phet.colorado.edu/sims/html/keplers-laws/latest/keplers-laws-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'định luật kepler', 'kepler', 'quỹ đạo elip', 'orbit', 'hành tinh']::text[], true, true, false, true, 'published'),
  ('my-solar-system', 'My Solar System', 'Tạo hệ gồm nhiều thiên thể, đặt vận tốc ban đầu và quan sát các quỹ đạo ổn định hoặc hỗn loạn.', 'Tạo hệ gồm nhiều thiên thể, đặt vận tốc ban đầu và quan sát các quỹ đạo ổn định hoặc hỗn loạn.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Thiên văn', 'Hệ hấp dẫn nhiều vật', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/my-solar-system', 'https://phet.colorado.edu/sims/html/my-solar-system/latest/my-solar-system_all.html', 'https://phet.colorado.edu/sims/html/my-solar-system/latest/my-solar-system_all.html', 'https://phet.colorado.edu/sims/html/my-solar-system/latest/my-solar-system-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'hệ mặt trời', 'solar system', 'quỹ đạo', 'orbit', 'hấp dẫn', 'hành tinh']::text[], true, true, false, true, 'published'),
  ('balancing-act', 'Balancing Act', 'Đặt vật nặng lên bập bênh để khám phá điều kiện cân bằng của đòn bẩy; có chế độ trò chơi thử thách.', 'Đặt vật nặng lên bập bênh để khám phá điều kiện cân bằng của đòn bẩy; có chế độ trò chơi thử thách.', (select id from public.subjects where slug = 'physics'), 5, 9, 'Cơ học', 'Cân bằng – Momen lực', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/balancing-act', 'https://phet.colorado.edu/sims/html/balancing-act/latest/balancing-act_all.html', 'https://phet.colorado.edu/sims/html/balancing-act/latest/balancing-act_all.html', 'https://phet.colorado.edu/sims/html/balancing-act/latest/balancing-act-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'cân bằng', 'balance', 'đòn bẩy', 'momen lực', 'torque']::text[], true, true, false, true, 'published'),
  ('collision-lab', 'Collision Lab', 'Khảo sát va chạm đàn hồi và không đàn hồi trong 1D và 2D, kiểm chứng định luật bảo toàn động lượng.', 'Khảo sát va chạm đàn hồi và không đàn hồi trong 1D và 2D, kiểm chứng định luật bảo toàn động lượng.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Cơ học', 'Động lượng và va chạm', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/collision-lab', 'https://phet.colorado.edu/sims/html/collision-lab/latest/collision-lab_all.html', 'https://phet.colorado.edu/sims/html/collision-lab/latest/collision-lab_all.html', 'https://phet.colorado.edu/sims/html/collision-lab/latest/collision-lab-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'va chạm', 'collision', 'động lượng', 'momentum', 'đàn hồi', 'elastic']::text[], true, true, false, true, 'published'),
  ('vector-addition', 'Vector Addition', 'Kéo thả các vectơ để cộng chúng, phân tích thành phần theo trục và quan sát độ lớn, hướng của vectơ tổng.', 'Kéo thả các vectơ để cộng chúng, phân tích thành phần theo trục và quan sát độ lớn, hướng của vectơ tổng.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Cơ học', 'Vectơ', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/vector-addition', 'https://phet.colorado.edu/sims/html/vector-addition/latest/vector-addition_all.html', 'https://phet.colorado.edu/sims/html/vector-addition/latest/vector-addition_all.html', 'https://phet.colorado.edu/sims/html/vector-addition/latest/vector-addition-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'vectơ', 'vector', 'tổng hợp vectơ', 'thành phần', 'component']::text[], true, true, false, true, 'published'),
  ('vector-addition-equations', 'Vector Addition: Equations', 'Thực hành các phương trình vectơ với hệ số và so sánh kết quả hình học với đại số.', 'Thực hành các phương trình vectơ với hệ số và so sánh kết quả hình học với đại số.', (select id from public.subjects where slug = 'mathematics'), 10, 12, 'Vectơ', 'Phép toán vectơ', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/vector-addition-equations', 'https://phet.colorado.edu/sims/html/vector-addition-equations/latest/vector-addition-equations_all.html', 'https://phet.colorado.edu/sims/html/vector-addition-equations/latest/vector-addition-equations_all.html', 'https://phet.colorado.edu/sims/html/vector-addition-equations/latest/vector-addition-equations-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'vectơ', 'vector', 'phương trình vectơ', 'hệ số', 'linear combination']::text[], true, true, false, true, 'published'),
  ('under-pressure', 'Under Pressure', 'Đo áp suất tại các độ sâu khác nhau trong bể nước với các chất lỏng và gia tốc trọng trường khác nhau.', 'Đo áp suất tại các độ sâu khác nhau trong bể nước với các chất lỏng và gia tốc trọng trường khác nhau.', (select id from public.subjects where slug = 'physics'), 8, 11, 'Chất lỏng', 'Áp suất chất lỏng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/under-pressure', 'https://phet.colorado.edu/sims/html/under-pressure/latest/under-pressure_all.html', 'https://phet.colorado.edu/sims/html/under-pressure/latest/under-pressure_all.html', 'https://phet.colorado.edu/sims/html/under-pressure/latest/under-pressure-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'áp suất', 'pressure', 'áp suất chất lỏng', 'fluid pressure', 'độ sâu', 'khí quyển']::text[], true, true, false, true, 'published'),
  ('density', 'Density', 'Xác định khối lượng riêng của các khối vật liệu bằng cách đo khối lượng và thể tích nước dâng.', 'Xác định khối lượng riêng của các khối vật liệu bằng cách đo khối lượng và thể tích nước dâng.', (select id from public.subjects where slug = 'physics'), 6, 9, 'Chất lỏng', 'Khối lượng riêng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/density', 'https://phet.colorado.edu/sims/html/density/latest/density_all.html', 'https://phet.colorado.edu/sims/html/density/latest/density_all.html', 'https://phet.colorado.edu/sims/html/density/latest/density-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'khối lượng riêng', 'density', 'thể tích', 'khối lượng', 'chìm nổi']::text[], true, true, false, true, 'published'),
  ('buoyancy', 'Buoyancy', 'Khảo sát lực đẩy Archimedes tác dụng lên vật nhúng trong chất lỏng và điều kiện vật nổi, lơ lửng, chìm.', 'Khảo sát lực đẩy Archimedes tác dụng lên vật nhúng trong chất lỏng và điều kiện vật nổi, lơ lửng, chìm.', (select id from public.subjects where slug = 'physics'), 8, 12, 'Chất lỏng', 'Lực đẩy Archimedes', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/buoyancy', 'https://phet.colorado.edu/sims/html/buoyancy/latest/buoyancy_all.html', 'https://phet.colorado.edu/sims/html/buoyancy/latest/buoyancy_all.html', 'https://phet.colorado.edu/sims/html/buoyancy/latest/buoyancy-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'lực đẩy archimedes', 'buoyancy', 'chìm nổi', 'khối lượng riêng', 'lực đẩy']::text[], true, true, false, true, 'published'),
  ('buoyancy-basics', 'Buoyancy: Basics', 'Phiên bản cơ bản giúp học sinh nhận biết vì sao có vật nổi, có vật chìm trong nước.', 'Phiên bản cơ bản giúp học sinh nhận biết vì sao có vật nổi, có vật chìm trong nước.', (select id from public.subjects where slug = 'physics'), 5, 8, 'Chất lỏng', 'Sự nổi', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/buoyancy-basics', 'https://phet.colorado.edu/sims/html/buoyancy-basics/latest/buoyancy-basics_all.html', 'https://phet.colorado.edu/sims/html/buoyancy-basics/latest/buoyancy-basics_all.html', 'https://phet.colorado.edu/sims/html/buoyancy-basics/latest/buoyancy-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'sự nổi', 'buoyancy', 'chìm nổi', 'khối lượng riêng']::text[], true, true, false, true, 'published'),
  ('wave-on-a-string', 'Wave on a String', 'Tạo sóng trên sợi dây, điều chỉnh biên độ, tần số, độ căng và quan sát phản xạ, sóng dừng.', 'Tạo sóng trên sợi dây, điều chỉnh biên độ, tần số, độ căng và quan sát phản xạ, sóng dừng.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Sóng', 'Sóng cơ', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/wave-on-a-string', 'https://phet.colorado.edu/sims/html/wave-on-a-string/latest/wave-on-a-string_all.html', 'https://phet.colorado.edu/sims/html/wave-on-a-string/latest/wave-on-a-string_all.html', 'https://phet.colorado.edu/sims/html/wave-on-a-string/latest/wave-on-a-string-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, array['Phân biệt biên độ, tần số, bước sóng.', 'Mô tả điều kiện hình thành sóng dừng trên dây.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'sóng', 'wave', 'sóng cơ', 'biên độ', 'tần số', 'sóng dừng', 'standing wave']::text[], true, true, false, true, 'published'),
  ('waves-intro', 'Waves Intro', 'Làm quen với sóng nước, sóng âm và sóng ánh sáng; so sánh biên độ, tần số của các loại sóng.', 'Làm quen với sóng nước, sóng âm và sóng ánh sáng; so sánh biên độ, tần số của các loại sóng.', (select id from public.subjects where slug = 'physics'), 6, 9, 'Sóng', 'Sóng nước, âm, ánh sáng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/waves-intro', 'https://phet.colorado.edu/sims/html/waves-intro/latest/waves-intro_all.html', 'https://phet.colorado.edu/sims/html/waves-intro/latest/waves-intro_all.html', 'https://phet.colorado.edu/sims/html/waves-intro/latest/waves-intro-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'sóng', 'wave', 'âm thanh', 'sound', 'sóng nước', 'ánh sáng']::text[], true, true, false, true, 'published'),
  ('wave-interference', 'Wave Interference', 'Quan sát giao thoa và nhiễu xạ của sóng nước, âm, ánh sáng qua hai nguồn kết hợp và khe hẹp.', 'Quan sát giao thoa và nhiễu xạ của sóng nước, âm, ánh sáng qua hai nguồn kết hợp và khe hẹp.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Sóng', 'Giao thoa', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/wave-interference', 'https://phet.colorado.edu/sims/html/wave-interference/latest/wave-interference_all.html', 'https://phet.colorado.edu/sims/html/wave-interference/latest/wave-interference_all.html', 'https://phet.colorado.edu/sims/html/wave-interference/latest/wave-interference-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'giao thoa', 'interference', 'nhiễu xạ', 'diffraction', 'khe young', 'double slit']::text[], true, true, false, true, 'published'),
