  ('bending-light', 'Bending Light', 'Khảo sát khúc xạ và phản xạ ánh sáng qua các môi trường, định luật Snell và phản xạ toàn phần.', 'Khảo sát khúc xạ và phản xạ ánh sáng qua các môi trường, định luật Snell và phản xạ toàn phần.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Quang học', 'Khúc xạ ánh sáng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/bending-light', 'https://phet.colorado.edu/sims/html/bending-light/latest/bending-light_all.html', 'https://phet.colorado.edu/sims/html/bending-light/latest/bending-light_all.html', 'https://phet.colorado.edu/sims/html/bending-light/latest/bending-light-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, array['Vận dụng định luật Snell để dự đoán góc khúc xạ.', 'Xác định điều kiện xảy ra phản xạ toàn phần.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'khúc xạ', 'refraction', 'phản xạ', 'reflection', 'chiết suất', 'định luật snell', 'lăng kính']::text[], true, true, false, true, 'published'),
  ('geometric-optics', 'Geometric Optics', 'Dựng ảnh qua thấu kính và gương, thay đổi tiêu cự, vị trí vật và quan sát ảnh thật, ảnh ảo.', 'Dựng ảnh qua thấu kính và gương, thay đổi tiêu cự, vị trí vật và quan sát ảnh thật, ảnh ảo.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Quang học', 'Thấu kính và gương', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/geometric-optics', 'https://phet.colorado.edu/sims/html/geometric-optics/latest/geometric-optics_all.html', 'https://phet.colorado.edu/sims/html/geometric-optics/latest/geometric-optics_all.html', 'https://phet.colorado.edu/sims/html/geometric-optics/latest/geometric-optics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'thấu kính', 'lens', 'gương', 'mirror', 'ảnh', 'tiêu cự', 'quang hình']::text[], true, true, false, true, 'published'),
  ('geometric-optics-basics', 'Geometric Optics: Basics', 'Phiên bản cơ bản giới thiệu cách thấu kính tạo ảnh bằng các tia sáng đặc biệt.', 'Phiên bản cơ bản giới thiệu cách thấu kính tạo ảnh bằng các tia sáng đặc biệt.', (select id from public.subjects where slug = 'physics'), 7, 10, 'Quang học', 'Thấu kính', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/geometric-optics-basics', 'https://phet.colorado.edu/sims/html/geometric-optics-basics/latest/geometric-optics-basics_all.html', 'https://phet.colorado.edu/sims/html/geometric-optics-basics/latest/geometric-optics-basics_all.html', 'https://phet.colorado.edu/sims/html/geometric-optics-basics/latest/geometric-optics-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'thấu kính', 'lens', 'ảnh', 'tia sáng']::text[], true, true, false, true, 'published'),
  ('color-vision', 'Color Vision', 'Pha trộn ánh sáng đỏ, lục, lam và dùng bộ lọc màu để hiểu mắt người cảm nhận màu sắc như thế nào.', 'Pha trộn ánh sáng đỏ, lục, lam và dùng bộ lọc màu để hiểu mắt người cảm nhận màu sắc như thế nào.', (select id from public.subjects where slug = 'physics'), 4, 9, 'Quang học', 'Màu sắc', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/color-vision', 'https://phet.colorado.edu/sims/html/color-vision/latest/color-vision_all.html', 'https://phet.colorado.edu/sims/html/color-vision/latest/color-vision_all.html', 'https://phet.colorado.edu/sims/html/color-vision/latest/color-vision-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'màu sắc', 'color', 'thị giác', 'ánh sáng', 'bộ lọc màu', 'rgb']::text[], true, true, false, true, 'published'),
  ('blackbody-spectrum', 'Blackbody Spectrum', 'Quan sát phổ bức xạ của vật đen thay đổi theo nhiệt độ và so sánh với Mặt Trời, bóng đèn, Trái Đất.', 'Quan sát phổ bức xạ của vật đen thay đổi theo nhiệt độ và so sánh với Mặt Trời, bóng đèn, Trái Đất.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Vật lý hiện đại', 'Bức xạ vật đen', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/blackbody-spectrum', 'https://phet.colorado.edu/sims/html/blackbody-spectrum/latest/blackbody-spectrum_all.html', 'https://phet.colorado.edu/sims/html/blackbody-spectrum/latest/blackbody-spectrum_all.html', 'https://phet.colorado.edu/sims/html/blackbody-spectrum/latest/blackbody-spectrum-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'bức xạ', 'vật đen', 'blackbody', 'quang phổ', 'spectrum', 'nhiệt độ']::text[], true, true, false, true, 'published'),
  ('molecules-and-light', 'Molecules and Light', 'Chiếu các loại ánh sáng (vi sóng, hồng ngoại, khả kiến, tử ngoại) vào phân tử và quan sát phân tử quay, dao động hay bị phân tách.', 'Chiếu các loại ánh sáng (vi sóng, hồng ngoại, khả kiến, tử ngoại) vào phân tử và quan sát phân tử quay, dao động hay bị phân tách.', (select id from public.subjects where slug = 'chemistry'), 6, 12, 'Tương tác ánh sáng – vật chất', null, 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/molecules-and-light', 'https://phet.colorado.edu/sims/html/molecules-and-light/latest/molecules-and-light_all.html', 'https://phet.colorado.edu/sims/html/molecules-and-light/latest/molecules-and-light_all.html', 'https://phet.colorado.edu/sims/html/molecules-and-light/latest/molecules-and-light-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'phân tử', 'molecule', 'ánh sáng', 'hồng ngoại', 'infrared', 'khí nhà kính']::text[], true, true, false, true, 'published'),
  ('models-of-the-hydrogen-atom', 'Models of the Hydrogen Atom', 'So sánh dự đoán của các mẫu nguyên tử hydro (Dalton, Thomson, Rutherford, Bohr, Schrödinger) với thực nghiệm.', 'So sánh dự đoán của các mẫu nguyên tử hydro (Dalton, Thomson, Rutherford, Bohr, Schrödinger) với thực nghiệm.', (select id from public.subjects where slug = 'physics'), 11, 12, 'Vật lý hiện đại', 'Mẫu nguyên tử', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/models-of-the-hydrogen-atom', 'https://phet.colorado.edu/sims/html/models-of-the-hydrogen-atom/latest/models-of-the-hydrogen-atom_all.html', 'https://phet.colorado.edu/sims/html/models-of-the-hydrogen-atom/latest/models-of-the-hydrogen-atom_all.html', 'https://phet.colorado.edu/sims/html/models-of-the-hydrogen-atom/latest/models-of-the-hydrogen-atom-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'mẫu nguyên tử', 'hydrogen atom', 'bohr', 'rutherford', 'quang phổ']::text[], true, true, false, true, 'published'),
  ('rutherford-scattering', 'Rutherford Scattering', 'Bắn hạt alpha vào nguyên tử để tái hiện thí nghiệm Rutherford và khám phá sự tồn tại của hạt nhân.', 'Bắn hạt alpha vào nguyên tử để tái hiện thí nghiệm Rutherford và khám phá sự tồn tại của hạt nhân.', (select id from public.subjects where slug = 'physics'), 10, 12, 'Vật lý hiện đại', 'Cấu tạo nguyên tử', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/rutherford-scattering', 'https://phet.colorado.edu/sims/html/rutherford-scattering/latest/rutherford-scattering_all.html', 'https://phet.colorado.edu/sims/html/rutherford-scattering/latest/rutherford-scattering_all.html', 'https://phet.colorado.edu/sims/html/rutherford-scattering/latest/rutherford-scattering-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'rutherford', 'tán xạ', 'hạt nhân', 'nucleus', 'hạt alpha']::text[], true, true, false, true, 'published'),
  ('states-of-matter', 'States of Matter', 'Quan sát chuyển động của phân tử ở thể rắn, lỏng, khí; đun nóng, làm lạnh và nén để thấy sự chuyển thể.', 'Quan sát chuyển động của phân tử ở thể rắn, lỏng, khí; đun nóng, làm lạnh và nén để thấy sự chuyển thể.', (select id from public.subjects where slug = 'chemistry'), 8, 12, 'Trạng thái của chất', 'Chuyển thể', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/states-of-matter', 'https://phet.colorado.edu/sims/html/states-of-matter/latest/states-of-matter_all.html', 'https://phet.colorado.edu/sims/html/states-of-matter/latest/states-of-matter_all.html', 'https://phet.colorado.edu/sims/html/states-of-matter/latest/states-of-matter-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, array['Mô tả chuyển động của phân tử ở ba thể rắn, lỏng, khí.', 'Giải thích sự chuyển thể khi thay đổi nhiệt độ và áp suất.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'trạng thái chất', 'states of matter', 'rắn lỏng khí', 'chuyển thể', 'nhiệt độ', 'phase']::text[], true, true, false, true, 'published'),
  ('states-of-matter-basics', 'States of Matter: Basics', 'Phiên bản cơ bản so sánh cách sắp xếp và chuyển động của các hạt ở ba trạng thái của chất.', 'Phiên bản cơ bản so sánh cách sắp xếp và chuyển động của các hạt ở ba trạng thái của chất.', (select id from public.subjects where slug = 'chemistry'), 4, 8, 'Trạng thái của chất', null, 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/states-of-matter-basics', 'https://phet.colorado.edu/sims/html/states-of-matter-basics/latest/states-of-matter-basics_all.html', 'https://phet.colorado.edu/sims/html/states-of-matter-basics/latest/states-of-matter-basics_all.html', 'https://phet.colorado.edu/sims/html/states-of-matter-basics/latest/states-of-matter-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'trạng thái chất', 'rắn', 'lỏng', 'khí', 'solid', 'liquid', 'gas']::text[], true, true, false, true, 'published'),
  ('gas-properties', 'Gas Properties', 'Bơm các phân tử khí vào bình và khảo sát mối quan hệ giữa áp suất, thể tích, nhiệt độ theo các định luật chất khí.', 'Bơm các phân tử khí vào bình và khảo sát mối quan hệ giữa áp suất, thể tích, nhiệt độ theo các định luật chất khí.', (select id from public.subjects where slug = 'physics'), 9, 12, 'Nhiệt học', 'Chất khí', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/gas-properties', 'https://phet.colorado.edu/sims/html/gas-properties/latest/gas-properties_all.html', 'https://phet.colorado.edu/sims/html/gas-properties/latest/gas-properties_all.html', 'https://phet.colorado.edu/sims/html/gas-properties/latest/gas-properties-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, array['Mô tả mối quan hệ giữa p, V, T của chất khí.', 'Giải thích áp suất chất khí bằng mô hình động học phân tử.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'chất khí', 'gas properties', 'áp suất', 'thể tích', 'nhiệt độ', 'định luật chất khí']::text[], true, true, false, true, 'published'),
  ('gases-intro', 'Gases Intro', 'Giới thiệu mô hình hạt của chất khí và mối liên hệ định tính giữa nhiệt độ, áp suất và thể tích.', 'Giới thiệu mô hình hạt của chất khí và mối liên hệ định tính giữa nhiệt độ, áp suất và thể tích.', (select id from public.subjects where slug = 'physics'), 7, 10, 'Nhiệt học', 'Chất khí', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/gases-intro', 'https://phet.colorado.edu/sims/html/gases-intro/latest/gases-intro_all.html', 'https://phet.colorado.edu/sims/html/gases-intro/latest/gases-intro_all.html', 'https://phet.colorado.edu/sims/html/gases-intro/latest/gases-intro-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'chất khí', 'gas', 'áp suất', 'nhiệt độ', 'phân tử']::text[], true, true, false, true, 'published'),
  ('diffusion', 'Diffusion', 'Quan sát hai loại khí khuếch tán vào nhau và ảnh hưởng của nhiệt độ, khối lượng phân tử đến tốc độ khuếch tán.', 'Quan sát hai loại khí khuếch tán vào nhau và ảnh hưởng của nhiệt độ, khối lượng phân tử đến tốc độ khuếch tán.', (select id from public.subjects where slug = 'chemistry'), 7, 11, 'Nhiệt học', 'Khuếch tán', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/diffusion', 'https://phet.colorado.edu/sims/html/diffusion/latest/diffusion_all.html', 'https://phet.colorado.edu/sims/html/diffusion/latest/diffusion_all.html', 'https://phet.colorado.edu/sims/html/diffusion/latest/diffusion-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 15, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'khuếch tán', 'diffusion', 'phân tử', 'nhiệt độ', 'khối lượng']::text[], true, true, false, true, 'published'),
  ('energy-forms-and-changes', 'Energy Forms and Changes', 'Xây dựng hệ thống chuyển hóa năng lượng từ nguồn đến thiết bị và theo dõi dòng năng lượng qua từng bộ phận.', 'Xây dựng hệ thống chuyển hóa năng lượng từ nguồn đến thiết bị và theo dõi dòng năng lượng qua từng bộ phận.', (select id from public.subjects where slug = 'physics'), 5, 9, 'Năng lượng', 'Chuyển hóa năng lượng', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/energy-forms-and-changes', 'https://phet.colorado.edu/sims/html/energy-forms-and-changes/latest/energy-forms-and-changes_all.html', 'https://phet.colorado.edu/sims/html/energy-forms-and-changes/latest/energy-forms-and-changes_all.html', 'https://phet.colorado.edu/sims/html/energy-forms-and-changes/latest/energy-forms-and-changes-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'năng lượng', 'energy', 'chuyển hóa năng lượng', 'nhiệt', 'điện năng', 'pin mặt trời']::text[], true, true, false, true, 'published'),
  ('greenhouse-effect', 'The Greenhouse Effect', 'Khám phá cách khí nhà kính và mây ảnh hưởng đến cân bằng năng lượng và nhiệt độ bề mặt Trái Đất.', 'Khám phá cách khí nhà kính và mây ảnh hưởng đến cân bằng năng lượng và nhiệt độ bề mặt Trái Đất.', (select id from public.subjects where slug = 'environmental-science'), 7, 12, 'Khí hậu', 'Hiệu ứng nhà kính', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/greenhouse-effect', 'https://phet.colorado.edu/sims/html/greenhouse-effect/latest/greenhouse-effect_all.html', 'https://phet.colorado.edu/sims/html/greenhouse-effect/latest/greenhouse-effect_all.html', 'https://phet.colorado.edu/sims/html/greenhouse-effect/latest/greenhouse-effect-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, array['Mô tả cách khí nhà kính hấp thụ và phát xạ bức xạ hồng ngoại.', 'Liên hệ nồng độ khí nhà kính với nhiệt độ Trái Đất.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'hiệu ứng nhà kính', 'greenhouse effect', 'biến đổi khí hậu', 'climate change', 'khí nhà kính', 'nhiệt độ']::text[], true, true, true, true, 'published'),
  ('build-an-atom', 'Build an Atom', 'Lắp ráp nguyên tử từ proton, neutron, electron; xác định nguyên tố, điện tích, số khối và chơi trò chơi kiểm tra.', 'Lắp ráp nguyên tử từ proton, neutron, electron; xác định nguyên tố, điện tích, số khối và chơi trò chơi kiểm tra.', (select id from public.subjects where slug = 'chemistry'), 7, 11, 'Cấu tạo nguyên tử', null, 'game', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/build-an-atom', 'https://phet.colorado.edu/sims/html/build-an-atom/latest/build-an-atom_all.html', 'https://phet.colorado.edu/sims/html/build-an-atom/latest/build-an-atom_all.html', 'https://phet.colorado.edu/sims/html/build-an-atom/latest/build-an-atom-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 30, array['Xác định nguyên tố dựa vào số proton.', 'Tính số khối và điện tích của nguyên tử/ion.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'nguyên tử', 'atom', 'proton', 'neutron', 'electron', 'ion', 'cấu tạo nguyên tử']::text[], true, true, true, true, 'published'),
  ('isotopes-and-atomic-mass', 'Isotopes and Atomic Mass', 'Tạo các đồng vị và tính nguyên tử khối trung bình dựa trên thành phần phần trăm đồng vị trong tự nhiên.', 'Tạo các đồng vị và tính nguyên tử khối trung bình dựa trên thành phần phần trăm đồng vị trong tự nhiên.', (select id from public.subjects where slug = 'chemistry'), 9, 12, 'Cấu tạo nguyên tử', 'Đồng vị', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/isotopes-and-atomic-mass', 'https://phet.colorado.edu/sims/html/isotopes-and-atomic-mass/latest/isotopes-and-atomic-mass_all.html', 'https://phet.colorado.edu/sims/html/isotopes-and-atomic-mass/latest/isotopes-and-atomic-mass_all.html', 'https://phet.colorado.edu/sims/html/isotopes-and-atomic-mass/latest/isotopes-and-atomic-mass-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'đồng vị', 'isotope', 'nguyên tử khối', 'atomic mass', 'neutron']::text[], true, true, false, true, 'published'),
  ('build-a-molecule', 'Build a Molecule', 'Ghép các nguyên tử thành phân tử và liên hệ công thức hóa học với cấu trúc phân tử.', 'Ghép các nguyên tử thành phân tử và liên hệ công thức hóa học với cấu trúc phân tử.', (select id from public.subjects where slug = 'chemistry'), 8, 11, 'Phân tử', 'Công thức phân tử', 'game', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/build-a-molecule', 'https://phet.colorado.edu/sims/html/build-a-molecule/latest/build-a-molecule_all.html', 'https://phet.colorado.edu/sims/html/build-a-molecule/latest/build-a-molecule_all.html', 'https://phet.colorado.edu/sims/html/build-a-molecule/latest/build-a-molecule-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'phân tử', 'molecule', 'công thức hóa học', 'nguyên tử']::text[], true, true, false, true, 'published'),
  ('molecule-shapes', 'Molecule Shapes', 'Xây dựng phân tử 3D và khám phá thuyết VSEPR: cặp electron liên kết, không liên kết ảnh hưởng đến góc liên kết.', 'Xây dựng phân tử 3D và khám phá thuyết VSEPR: cặp electron liên kết, không liên kết ảnh hưởng đến góc liên kết.', (select id from public.subjects where slug = 'chemistry'), 10, 12, 'Liên kết hóa học', 'Hình học phân tử', 'model', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/molecule-shapes', 'https://phet.colorado.edu/sims/html/molecule-shapes/latest/molecule-shapes_all.html', 'https://phet.colorado.edu/sims/html/molecule-shapes/latest/molecule-shapes_all.html', 'https://phet.colorado.edu/sims/html/molecule-shapes/latest/molecule-shapes-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'hình dạng phân tử', 'molecule shapes', 'vsepr', 'góc liên kết', 'cặp electron']::text[], true, true, false, true, 'published'),
  ('molecule-shapes-basics', 'Molecule Shapes: Basics', 'Phiên bản cơ bản giới thiệu hình học phân tử và cách các nhóm electron sắp xếp xa nhau nhất.', 'Phiên bản cơ bản giới thiệu hình học phân tử và cách các nhóm electron sắp xếp xa nhau nhất.', (select id from public.subjects where slug = 'chemistry'), 9, 11, 'Liên kết hóa học', 'Hình học phân tử', 'model', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/molecule-shapes-basics', 'https://phet.colorado.edu/sims/html/molecule-shapes-basics/latest/molecule-shapes-basics_all.html', 'https://phet.colorado.edu/sims/html/molecule-shapes-basics/latest/molecule-shapes-basics_all.html', 'https://phet.colorado.edu/sims/html/molecule-shapes-basics/latest/molecule-shapes-basics-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'hình dạng phân tử', 'vsepr', 'phân tử 3d']::text[], true, true, false, true, 'published'),
  ('molecule-polarity', 'Molecule Polarity', 'Thay đổi độ âm điện của nguyên tử để thấy liên kết và phân tử trở nên phân cực, đặt phân tử trong điện trường.', 'Thay đổi độ âm điện của nguyên tử để thấy liên kết và phân tử trở nên phân cực, đặt phân tử trong điện trường.', (select id from public.subjects where slug = 'chemistry'), 10, 12, 'Liên kết hóa học', 'Độ phân cực', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/molecule-polarity', 'https://phet.colorado.edu/sims/html/molecule-polarity/latest/molecule-polarity_all.html', 'https://phet.colorado.edu/sims/html/molecule-polarity/latest/molecule-polarity_all.html', 'https://phet.colorado.edu/sims/html/molecule-polarity/latest/molecule-polarity-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'advanced', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'phân cực', 'polarity', 'độ âm điện', 'electronegativity', 'liên kết']::text[], true, true, false, true, 'published'),
  ('balancing-chemical-equations', 'Balancing Chemical Equations', 'Cân bằng phương trình hóa học bằng cách điều chỉnh hệ số, có hình ảnh trực quan và trò chơi nhiều cấp độ.', 'Cân bằng phương trình hóa học bằng cách điều chỉnh hệ số, có hình ảnh trực quan và trò chơi nhiều cấp độ.', (select id from public.subjects where slug = 'chemistry'), 8, 11, 'Phản ứng hóa học', 'Cân bằng phương trình', 'game', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/balancing-chemical-equations', 'https://phet.colorado.edu/sims/html/balancing-chemical-equations/latest/balancing-chemical-equations_all.html', 'https://phet.colorado.edu/sims/html/balancing-chemical-equations/latest/balancing-chemical-equations_all.html', 'https://phet.colorado.edu/sims/html/balancing-chemical-equations/latest/balancing-chemical-equations-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'beginner', 20, array['Cân bằng được phương trình hóa học đơn giản.', 'Giải thích định luật bảo toàn khối lượng ở cấp độ nguyên tử.']::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'cân bằng phương trình', 'balancing chemical equations', 'phương trình hóa học', 'bảo toàn khối lượng']::text[], true, true, false, true, 'published'),
  ('reactants-products-and-leftovers', 'Reactants, Products and Leftovers', 'Tìm hiểu chất phản ứng hết, chất dư qua ví dụ làm bánh sandwich và các phản ứng hóa học thực tế.', 'Tìm hiểu chất phản ứng hết, chất dư qua ví dụ làm bánh sandwich và các phản ứng hóa học thực tế.', (select id from public.subjects where slug = 'chemistry'), 8, 11, 'Phản ứng hóa học', 'Chất phản ứng hết – dư', 'game', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/reactants-products-and-leftovers', 'https://phet.colorado.edu/sims/html/reactants-products-and-leftovers/latest/reactants-products-and-leftovers_all.html', 'https://phet.colorado.edu/sims/html/reactants-products-and-leftovers/latest/reactants-products-and-leftovers_all.html', 'https://phet.colorado.edu/sims/html/reactants-products-and-leftovers/latest/reactants-products-and-leftovers-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 30, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'chất phản ứng', 'reactants', 'sản phẩm', 'products', 'chất dư', 'limiting reactant', 'hóa học lượng']::text[], true, true, false, true, 'published'),
  ('concentration', 'Concentration', 'Thêm chất tan, nước hoặc cho bay hơi để khám phá nồng độ dung dịch và trạng thái bão hòa.', 'Thêm chất tan, nước hoặc cho bay hơi để khám phá nồng độ dung dịch và trạng thái bão hòa.', (select id from public.subjects where slug = 'chemistry'), 9, 12, 'Dung dịch', 'Nồng độ', 'simulation', (select id from public.sources where slug = 'phet'), 'https://phet.colorado.edu/en/simulations/concentration', 'https://phet.colorado.edu/sims/html/concentration/latest/concentration_all.html', 'https://phet.colorado.edu/sims/html/concentration/latest/concentration_all.html', 'https://phet.colorado.edu/sims/html/concentration/latest/concentration-600.png', 'multi', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'creative_commons', 'intermediate', 20, '{}'::text[], array['Máy tính, máy tính bảng hoặc bảng tương tác có trình duyệt web']::text[], array['phet', 'html5', 'nồng độ', 'concentration', 'dung dịch', 'bão hòa', 'saturated', 'chất tan']::text[], true, true, false, true, 'published'),
